#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_eval_and_optimize() {
        let mut store = HashMap::new();
        store.insert("x".to_string(), 5);
        store.insert("y".to_string(), 10);

        // ((x * 1) + (0 * y))  => optimize at root: it's a Plus node
        let expr = Exp::Plus(
            Box::new(Exp::Mult(
                Box::new(Exp::Var("x".into())),
                Box::new(Exp::Const(1)),
            )),
            Box::new(Exp::Mult(
                Box::new(Exp::Const(0)),
                Box::new(Exp::Var("y".into())),
            )),
        );

        let original = expr.clone();
        let v0 = original.eval(&store);

        // optimize only at the topmost Plus:
        let opt1 = expr.optimize();
        assert_eq!(opt1, original);
        assert_eq!(opt1.eval(&store), v0);

        // Now explicitly optimize the two Mult subexpressions:
        let mult1 = Exp::Mult(
            Box::new(Exp::Var("x".into())),
            Box::new(Exp::Const(1)),
        );
        let mult2 = Exp::Mult(
            Box::new(Exp::Const(0)),
            Box::new(Exp::Var("y".into())),
        );
        assert_eq!(mult1.optimize(), Exp::Var("x".into()));
        assert_eq!(mult2.optimize(), Exp::Const(0));

        // As a full expression if we had recursively optimized:
        let full_opt = Exp::Plus(
            Box::new(mult1.optimize()),
            Box::new(mult2.optimize()),
        )
        .optimize();
        // Now the root Plus sees (x + 0) and reduces to x
        assert_eq!(full_opt, Exp::Var("x".into()));
        assert_eq!(full_opt.eval(&store), 5);
    }
}